const items = $input.all();

const source =
  items.find(i => i.json.scanner === 'scan-source.sh')?.json ?? {};

const db =
  items.find(i => i.json.scanner === 'scan-database.sh')?.json ?? {};

const ss = source.summary ?? {};
const ds = db.summary ?? {};

const sourceFindings = Array.isArray(source.critical_findings)
  ? source.critical_findings
  : (
      Array.isArray(source.findings)
        ? source.findings.filter(f => f.severity === 'critical')
        : []
    );

const dbFindings = Array.isArray(db.critical_findings)
  ? db.critical_findings
  : (
      Array.isArray(db.findings)
        ? db.findings.filter(f => f.severity === 'critical')
        : []
    );

const criticalFindings = [
  ...sourceFindings,
  ...dbFindings
];

const totalCritical = criticalFindings.length;

const sourceName =
  source.source ??
  $node['Validate Inputs']?.json?.source_folder ??
  'unknown';

const clip = (value, max = 900) => {
  const s = String(value ?? '');
  return s.length > max
    ? s.slice(0, max) + '…'
    : s;
};


// ------------------------------------------------------------
// Critical findings text
// ------------------------------------------------------------

const criticalText = criticalFindings
  .map((f, index) => {

    const file =
      f.relative_file ??
      f.file ??
      'unknown';

    const score =
      f.score !== undefined
        ? `Score: **${f.score}**`
        : '';

    const confidence =
      f.confidence
        ? `Confidence: **${f.confidence}**`
        : '';

    const reason =
      f.reason
        ? `\n${clip(f.reason, 500)}`
        : '';

    return (
      `${index + 1}. **${clip(file, 250)}**\n` +
      `${score} ${confidence}` +
      `${reason}`
    );
  })
  .join('\n\n');


// ------------------------------------------------------------
// Database critical findings
// ------------------------------------------------------------

const databaseCriticalText = dbFindings
  .map((f, index) => {

    const target =
      [f.database, f.table, f.column]
        .filter(Boolean)
        .join('.') ||
      f.relative_file ||
      f.file ||
      f.type ||
      'unknown';

    return (
      `${index + 1}. **${clip(target, 250)}**` +
      `${f.reason ? `\n${clip(f.reason, 500)}` : ''}`
    );
  })
  .join('\n\n');


// ------------------------------------------------------------
// Discord fields
// ------------------------------------------------------------

const fields = [];

fields.push({
  name: '🚨 Critical Files',
  value: totalCritical > 0
    ? clip(criticalText, 1024)
    : 'None',
  inline: false
});


// Database critical findings, nếu có
if (databaseCriticalText) {
  fields.push({
    name: '🗄️ Database Critical Findings',
    value: clip(databaseCriticalText, 1024),
    inline: false
  });
}


// Scanner statistics
fields.push({
  name: '📊 Scan Summary',
  value:
    `Files scanned: **${source.files_scanned ?? 0}**\n` +
    `Critical: **${ss.critical ?? totalCritical}**\n` +
    `High: **${ss.high ?? 0}**\n` +
    `Medium: **${ss.medium ?? 0}**\n` +
    `Low: **${ss.low ?? 0}**`,
  inline: true
});


// Database summary
fields.push({
  name: '🗄️ Database Scan',
  value:
    `Total: **${ds.total ?? 0}**\n` +
    `Critical: **${ds.critical ?? 0}**\n` +
    `High: **${ds.high ?? 0}**\n` +
    `Medium: **${ds.medium ?? 0}**\n` +
    `Low: **${ds.low ?? 0}**`,
  inline: true
});


// ------------------------------------------------------------
// Discord response
// ------------------------------------------------------------

return [
  {
    json: {
      username: 'aaPanel Security Scanner',

      embeds: [
        {
          title:
            totalCritical > 0
              ? '🔴 Security Scan — CRITICAL FINDINGS'
              : '🟢 Security Scan — CLEAN',

          description:
            `**Source:** \`${clip(sourceName, 300)}\`\n` +
            `**Mode:** READ-ONLY — no files or database records were modified.`,

          color:
            totalCritical > 0
              ? 15548997
              : 5763719,

          fields,

          footer: {
            text:
              `aaPanel Security Scanner v${source.version ?? '4.1'} • READ-ONLY`
          },

          timestamp:
            new Date().toISOString()
        }
      ]
    }
  }
];

const source = String(
  $json['Source folder'] ??
  $json['source_folder'] ??
  ''
).trim();

const dbName = String(
  $json['Database name'] ??
  $json['database_name'] ??
  ''
).trim();

const password = String(
  $json['Database password'] ??
  $json['database_password'] ??
  ''
);

if (!source) {
  throw new Error('Source folder is required.');
}

if (!source.startsWith('/www/wwwroot/')) {
  throw new Error(
    'Source folder must be below /www/wwwroot/.'
  );
}

if (!dbName) {
  throw new Error('Database name is required.');
}

if (!/^[A-Za-z0-9_$-]+$/.test(dbName)) {
  throw new Error('Invalid database name.');
}

if (!password) {
  throw new Error('Database password is required.');
}

return [{
  json: {
    source_folder: source,
    database_name: dbName,
    database_password: password,
    scanner_api_url: 'http://scanner-api:8080',
    scan_started_at: new Date().toISOString()
  }
}];

const items = $input.all();

const source =
  items.find(i => i.json.scanner === 'scan-source.sh')?.json ?? {};

const db =
  items.find(i => i.json.scanner === 'scan-database.sh')?.json ?? {};

const sourceFindings = Array.isArray(source.findings)
  ? source.findings
  : [];

const dbFindings = Array.isArray(db.findings)
  ? db.findings
  : [];


// ------------------------------------------------------------
// Chỉ đưa findings KHÔNG phải critical vào TXT
// ------------------------------------------------------------

const findings = [
  ...sourceFindings,
  ...dbFindings
].filter(f => f.severity !== 'critical');


// ------------------------------------------------------------
// Sort: High -> Medium -> Low
// ------------------------------------------------------------

const severityOrder = {
  high: 1,
  medium: 2,
  low: 3
};

findings.sort(
  (a, b) =>
    (severityOrder[a.severity] ?? 99) -
    (severityOrder[b.severity] ?? 99)
);


// ------------------------------------------------------------
// Source
// ------------------------------------------------------------

const sourceName =
  source.source ??
  'unknown';


// ------------------------------------------------------------
// Header
// ------------------------------------------------------------

const lines = [];

lines.push(
  'aaPanel Security Scanner - Detailed Findings'
);

lines.push(
  '============================================================'
);

lines.push(
  `Source: ${sourceName}`
);

lines.push(
  `Scanner: ${source.scanner ?? 'scan-source.sh'}`
);

lines.push(
  `Version: ${source.version ?? 'unknown'}`
);

lines.push(
  `Mode: ${source.mode ?? 'read-only'}`
);

lines.push(
  `Scanned at: ${source.scanned_at ?? new Date().toISOString()}`
);

lines.push('');

lines.push(
  'IMPORTANT:'
);

lines.push(
  'This file contains non-critical findings for manual review.'
);

lines.push(
  'Critical findings are reported separately to Discord.'
);

lines.push('');


// ------------------------------------------------------------
// Summary
// ------------------------------------------------------------

lines.push(
  'SUMMARY'
);

lines.push(
  '------------------------------------------------------------'
);

lines.push(
  `Total findings: ${findings.length}`
);

lines.push(
  `High: ${findings.filter(f => f.severity === 'high').length}`
);

lines.push(
  `Medium: ${findings.filter(f => f.severity === 'medium').length}`
);

lines.push(
  `Low: ${findings.filter(f => f.severity === 'low').length}`
);

lines.push('');


// ------------------------------------------------------------
// Findings
// ------------------------------------------------------------

if (findings.length === 0) {

  lines.push(
    'No non-critical findings.'
  );

} else {

  findings.forEach((f, index) => {

    lines.push(
      `#${index + 1} [${String(f.severity ?? 'unknown').toUpperCase()}]`
    );

    lines.push(
      `File: ${f.relative_file ?? f.file ?? 'unknown'}`
    );

    if (f.line) {
      lines.push(
        `Line: ${f.line}`
      );
    }

    lines.push(
      `Type: ${f.type ?? 'unknown'}`
    );

    lines.push(
      `Rule: ${f.rule ?? 'unknown'}`
    );

    lines.push(
      `Confidence: ${f.confidence ?? 'unknown'}`
    );

    lines.push(
      `Score: ${f.score ?? 0}`
    );

    lines.push(
      `Reason: ${f.reason ?? ''}`
    );

    lines.push(
      `Evidence: ${f.match ?? ''}`
    );

    lines.push(
      '------------------------------------------------------------'
    );

  });

}


// ------------------------------------------------------------
// Create TXT
// ------------------------------------------------------------

const content = lines.join('\n');

const filename =
  `security-findings-${new Date()
    .toISOString()
    .replace(/[:.]/g, '-')
  }.txt`;

const binaryData =
  await this.helpers.prepareBinaryData(
    Buffer.from(content, 'utf8'),
    filename,
    'text/plain; charset=utf-8'
  );


return [{
  json: {
    filename,
    findings_count: findings.length
  },
  binary: {
    data: binaryData
  }
}];
